-- library_actor(uuid,boolean)
CREATE OR REPLACE FUNCTION public.library_actor(a uuid, allow_closed boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p profiles;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' OR a IS NULL THEN
  RAISE EXCEPTION 'LIBRARY_FORBIDDEN' USING ERRCODE='42501'; END IF;
